Trajectories
Forge to prepare manuscript figures.
Code
g &lt;- read_tsv("data/derived_data/trajectories.tsv") |&gt; 
  ggplot(aes(rel_year, y, col = paste(site, plot))) +
  geom_point(
    data = read_tsv("data/derived_data/data.tsv") |&gt; 
      select(rel_year, site, plot, dist_obs, diversity_q0_sp, diversity_q0_sp_rar) |&gt; 
      rename(Raw = diversity_q0_sp, Rarefied = diversity_q0_sp_rar) |&gt; 
      pivot_longer(cols = Raw:Rarefied, names_to = "type", values_to = "y"),
    alpha = .5
  ) +
  geom_line() +
  ggh4x::facet_grid2(site ~ type, scales = "free_y", independent = "y") +
  theme_bw() +
  xlab(expression("Time post logging" ~ "[ yr ]")) +
  ylab(expression("Species richness" ~ "[" ~ N ~ ha^{
    -1
  } ~ "100 trees"^{
    -1
  } ~ "]")) +
  geom_vline(xintercept = 0) +
  scale_color_manual(
    guide = "none",
    values = rainbow(242, s = .6, v = .9)[sample(1:242, 242)]
  )
cowplot::save_plot("figures/trajectories.png",
                   plot = g,
                   base_width = 8,
                   base_height = 10,
                   dpi = 300,
                   bg = "white"
)
g





Fig 3: The trajectories of species diversity recovery over time following a selective logging disturbance are shown across continents, sites and plots. The x-axis represents the number of years post-disturbance and the y-axis represents either rarefied (left) or raw (right) species richness. The lines represent the modelled recovery trajectories, while the points show the observations.

Intermediate maximum timing


Code
data &lt;- read_tsv("data/derived_data/data.tsv")
ind &lt;- data |&gt;
  select(site, sitenum, plot, plotnum, dist_obs) |&gt;
  unique()
g &lt;- file.path("chains", "rarefied") |&gt; 
  list.files(full.names = TRUE) |&gt; 
  as_cmdstan_fit() |&gt; 
  (\(x) x$summary("tau0_s"))() |&gt; 
  separate(variable, c("variable", "s", "sitenum"), convert = TRUE) |&gt;
  select(-s) |&gt;
  left_join(select(ind, site, sitenum)) |&gt;
  mutate_at(c("median", "q5", "q95"), ~ . + 3) |&gt;
  ggplot(aes(median, reorder(site, median))) +
  geom_vline(xintercept = c(0, 30), col = "darkgrey") +
  geom_segment(aes(
    x = (median - sd),
    xend = (median + sd)
  )) +
  geom_segment(aes(x = q5, xend = q95), size = .1) +
  geom_point() +
  theme_bw() +
  xlab(expression(tau ~ "[ yr ]")) +
  ylab("")
cowplot::save_plot("figures/tau.png",
                   plot = g,
                   base_width = 6,
                   base_height = 4,
                   dpi = 300,
                   bg = "white"
)
g





